<?php

use Modules\Core\Models\User;use Modules\Finance\Models\AccountMapping;use Modules\Finance\Models\ArInvoice;use Modules\Finance\Models\FinanceTaxLine;use Modules\Finance\Models\Journal;use Modules\Finance\Models\TaxCode;use Modules\Finance\Services\ArApService;use Modules\Finance\Services\FinanceTaxService;use Modules\Finance\Services\FxRateService;use Modules\MasterData\Models\ChartOfAccount;use Modules\MasterData\Models\Currency;use Modules\MasterData\Models\Customer;use Modules\MasterData\Models\ExchangeRate;use Modules\MasterData\Models\Supplier;use Modules\Purchasing\Models\SupplierInvoice;use Modules\Sales\Models\SalesOrder;
function stage10dCoa(string$code,string$type,string$normal):ChartOfAccount{return ChartOfAccount::create(['company_id'=>1,'code'=>$code.'-'.uniqid(),'name'=>$code,'type'=>$type,'normal_balance'=>$normal]);}function stage10dMap(string$event,ChartOfAccount$d,ChartOfAccount$c):void{AccountMapping::create(['company_id'=>1,'event'=>$event,'debit_account_id'=>$d->id,'credit_account_id'=>$c->id]);}
it('AP finance snapshot menghitung input tax dan withholding sekali saja',function(){$u=User::factory()->create(['company_id'=>1]);$s=Supplier::create(['company_id'=>1,'code'=>'SUP-'.uniqid(),'name'=>'Vendor','type'=>'FABRIC']);$input=TaxCode::create(['company_id'=>1,'code'=>'VAT11','name'=>'VAT Input','kind'=>'INPUT_TAX','rate_pct'=>11,'created_by'=>$u->id]);$wh=TaxCode::create(['company_id'=>1,'code'=>'WHT2','name'=>'WHT Payable','kind'=>'WITHHOLDING_PAYABLE','rate_pct'=>2,'created_by'=>$u->id]);$ap=SupplierInvoice::create(['company_id'=>1,'doc_no'=>'AP-'.uniqid(),'supplier_id'=>$s->id,'invoice_date'=>now()->toDateString(),'total_amount'=>1000,'match_status'=>'MATCHED','status'=>'APPROVED','created_by'=>$u->id]);$inputTax=stage10dCoa('INPUT','ASSET','DEBIT');$apControl=stage10dCoa('AP','LIABILITY','CREDIT');$withholding=stage10dCoa('WHT','LIABILITY','CREDIT');stage10dMap('AP_TAX',$inputTax,$apControl);stage10dMap('AP_WITHHOLDING',$apControl,$withholding);$done=app(ArApService::class)->finalizeApFinance($ap,['taxes'=>[['tax_code_id'=>$input->id],['tax_code_id'=>$wh->id]]],$u);expect((float)$done->subtotal_amount)->toBe(1000.0)->and((float)$done->tax_amount)->toBe(110.0)->and((float)$done->withholding_amount)->toBe(20.0)->and((float)$done->total_amount)->toBe(1090.0)->and($done->taxLines)->toHaveCount(2);app(ArApService::class)->finalizeApFinance($done,[],$u);})->throws(RuntimeException::class,'sudah difinalisasi');
it('AR settlement membukukan realized FX gain dengan kurs pembayaran',function(){$u=User::factory()->create(['company_id'=>1]);$usd=Currency::create(['company_id'=>1,'code'=>'USD','name'=>'US Dollar']);$c=Customer::create(['company_id'=>1,'code'=>'C-'.uniqid(),'name'=>'Buyer']);$so=SalesOrder::create(['company_id'=>1,'doc_no'=>'SO-'.uniqid(),'customer_id'=>$c->id,'order_date'=>now()->toDateString(),'status'=>'CLOSED','created_by'=>$u->id]);$ar=ArInvoice::create(['company_id'=>1,'doc_no'=>'AR-'.uniqid(),'customer_id'=>$c->id,'sales_order_id'=>$so->id,'invoice_date'=>now()->toDateString(),'currency_id'=>$usd->id,'exchange_rate'=>15000,'subtotal_amount'=>100,'total_amount'=>100,'base_amount'=>1500000,'finance_finalized_at'=>now(),'status'=>'OPEN','created_by'=>$u->id]);$cash=stage10dCoa('CASH','ASSET','DEBIT');$receivable=stage10dCoa('AR','ASSET','DEBIT');$gain=stage10dCoa('GAIN','REVENUE','CREDIT');stage10dMap('AR_PAYMENT',$cash,$receivable);stage10dMap('AR_FX_GAIN',$receivable,$gain);$p=app(ArApService::class)->recordArPayment($ar,['amount'=>100,'exchange_rate'=>16000],$u);expect((float)$p->base_amount)->toBe(1600000.0)->and((float)$p->realized_fx_amount)->toBe(100000.0)->and($ar->fresh()->status)->toBe('PAID')->and(Journal::withoutGlobalScopes()->where('event','AR_FX_GAIN')->count())->toBe(1);});
it('AP settlement membukukan realized FX loss',function(){$u=User::factory()->create(['company_id'=>1]);$usd=Currency::create(['company_id'=>1,'code'=>'USD','name'=>'US Dollar']);$s=Supplier::create(['company_id'=>1,'code'=>'S-'.uniqid(),'name'=>'Vendor','type'=>'FABRIC']);$ap=SupplierInvoice::create(['company_id'=>1,'doc_no'=>'AP-'.uniqid(),'supplier_id'=>$s->id,'invoice_date'=>now()->toDateString(),'currency_id'=>$usd->id,'exchange_rate'=>15000,'subtotal_amount'=>100,'total_amount'=>100,'base_amount'=>1500000,'finance_finalized_at'=>now(),'match_status'=>'MATCHED','status'=>'APPROVED','created_by'=>$u->id]);$payable=stage10dCoa('AP','LIABILITY','CREDIT');$cash=stage10dCoa('CASH','ASSET','DEBIT');$loss=stage10dCoa('LOSS','EXPENSE','DEBIT');stage10dMap('AP_PAYMENT',$payable,$cash);stage10dMap('AP_FX_LOSS',$loss,$payable);$p=app(ArApService::class)->recordApPayment($ap,['amount'=>100,'exchange_rate'=>16000],$u);expect((float)$p->base_amount)->toBe(1600000.0)->and((float)$p->realized_fx_amount)->toBe(-100000.0)->and($ap->fresh()->status)->toBe('PAID')->and(Journal::withoutGlobalScopes()->where('event','AP_FX_LOSS')->count())->toBe(1);});
it('rate lookup menggunakan rate terakhir pada tanggal settlement',function(){$usd=Currency::create(['company_id'=>1,'code'=>'USD','name'=>'US Dollar']);ExchangeRate::create(['company_id'=>1,'currency_id'=>$usd->id,'rate_date'=>'2026-08-01','rate'=>15000]);ExchangeRate::create(['company_id'=>1,'currency_id'=>$usd->id,'rate_date'=>'2026-08-10','rate'=>15500]);expect(app(FxRateService::class)->resolve(1,$usd->id,'2026-08-09'))->toBe(15000.0)->and(app(FxRateService::class)->resolve(1,$usd->id,'2026-08-11'))->toBe(15500.0);});
it('tax line snapshot bersifat immutable',function(){$u=User::factory()->create(['company_id'=>1]);$tax=TaxCode::create(['company_id'=>1,'code'=>'VAT','name'=>'VAT','kind'=>'OUTPUT_TAX','rate_pct'=>10]);$calc=app(FinanceTaxService::class)->calculate(1,'AR_INVOICE',100,[['tax_code_id'=>$tax->id]]);app(FinanceTaxService::class)->store('AR_INVOICE',99,$calc['lines'],$u->id);FinanceTaxLine::firstOrFail()->update(['amount'=>999]);})->throws(LogicException::class,'immutable');
